<div class="confirm-modal" id="archive-confirm-modal" hidden><div class="confirm-backdrop"></div><div class="confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="archive-confirm-title"><div class="confirm-icon">!</div><h2 id="archive-confirm-title">Archive this item?</h2><p id="archive-confirm-message">The item will be hidden from the current catalog and outgoing selection.</p><div class="confirm-actions"><button type="button" class="button ghost" id="archive-confirm-cancel">Cancel</button><button type="button" class="button primary" id="archive-confirm-continue">Archive item</button></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const modal=document.querySelector('#archive-confirm-modal'),message=document.querySelector('#archive-confirm-message'),title=document.querySelector('#archive-confirm-title'),cancel=document.querySelector('#archive-confirm-cancel'),continueButton=document.querySelector('#archive-confirm-continue');let pending=null;const close=()=>{modal.hidden=true;pending=null};document.querySelectorAll('.archive-confirm-form').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();pending=form;title.textContent='Archive this item?';continueButton.textContent='Archive item';message.textContent=form.dataset.confirmMessage;modal.hidden=false;cancel.focus()}));document.querySelectorAll('form[action*="/restore"]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();pending=form;title.textContent='Restore this item?';continueButton.textContent='Restore item';message.textContent='This item will return to the current catalog and become available for outgoing selection.';modal.hidden=false;cancel.focus()}));cancel.onclick=close;continueButton.onclick=()=>{if(pending){const form=pending;close();form.submit()}};modal.querySelector('.confirm-backdrop').onclick=close;document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)close()})});</script>
